def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        for a, b in zip(cols, cols[1:]):
            if grid[r][a] == grid[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rows, rows[1:]):
            if grid[a][c] == grid[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    return out

def transform(grid):
    bg=max(set(v for row in grid for v in row), key=lambda x:sum(row.count(x) for row in grid))
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    out=[row[:] for row in grid]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in (r0,r1) or c in (c0,c1)) and grid[r][c]==bg: out[r][c]=2
    return out
